import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('pyoderma-gangrenosum',
  kf=["**Pyoderma gangrenosum (PG)** is a rare **neutrophilic dermatosis**: a rapidly enlarging, very painful ulcer with a **violaceous, undermined edge**.",
      "Not an infection and not gangrene; often starts as a pustule after minor trauma (**pathergy**).",
      "About half have an associated disease: **IBD**, inflammatory arthritis, haematological disorders (MGUS, myeloma, leukaemia).",
      "Diagnosis of exclusion: biopsy the edge, swab, exclude vasculitis, infection and malignancy.",
      "Avoid debridement and surgery; urgent dermatology for potent topical/systemic steroids or ciclosporin, biologics."],
  epi=[{"t": "**Who**", "sub": ["Rare (about 1 in 100,000 per year); adults 20–50; slightly more women."]}],
  myths=["**\"Debride it like any ulcer\"**: surgery worsens PG through pathergy."],
  patho_lead="PG is driven by **overactive neutrophils** in otherwise sterile tissue.",
  mech=[("Immune dysregulation", "Innate immune overactivity (IL-1, IL-8, IL-17, TNF-α) recruits neutrophils."),
        ("Pathergy", "Minor trauma triggers an exaggerated neutrophilic response at the site."),
        ("Destructive ulcer", "Neutrophils destroy dermis and fat, undermining the edge.", "v4-pg-undermined.jpg", "Pyoderma gangrenosum: a deep ulcer packed with neutrophils, with an overhanging violaceous (undermined) edge."),
        ("Cribriform healing", "Ulcers heal with thin, sieve-like (cribriform) scars.")],
  histo=["Dense neutrophilic infiltrate without vasculitis or organisms; findings are supportive, not specific (Delphi/PARACELSUS criteria)."],
  special=[{"t": "**Peristomal PG**", "sub": ["Around stomas in IBD; involve the stoma team."]}],
  comp=["Severe pain, infection, scarring; recurrence; complications of immunosuppression."],
  prog=["Healing takes months; relapses common."],
  see_also=["venous-leg-ulcer", "arterial-leg-ulcer", "cutaneous-vasculitis-approach", "erythema-nodosum", "biologics-systemics"])

E('discoid-lupus',
  kf=["**Discoid lupus erythematosus (DLE)** is chronic cutaneous lupus: scaly red plaques that heal with **scarring, atrophy and pigment change**.",
      "Face, ears (conchal bowl), scalp (scarring alopecia); photosensitive; follicular plugging ('carpet-tack' scale).",
      "About 5–10% progress to systemic lupus; check FBC, ANA, ENA, urine.",
      "Strict photoprotection, **stop smoking**, potent topical steroid; **hydroxychloroquine** via dermatology.",
      "Long-standing scars can develop SCC."],
  epi=[{"t": "**Who**", "sub": ["Women 20–40; more common and more scarring in people of African descent."]}],
  myths=["**\"It's just eczema on the face\"**: scarring, follicular plugs and ear involvement point to DLE."],
  patho_lead="DLE is an **interface attack** on basal keratinocytes and hair follicles, triggered by UV.",
  mech=[("UV injury", "UV causes keratinocyte apoptosis and exposure of nuclear antigens."),
        ("Interferon response", "Plasmacytoid dendritic cells produce type I interferon, recruiting cytotoxic T cells."),
        ("Interface damage", "T cells attack the basal layer and follicular epithelium."),
        ("Scarring", "Follicles are destroyed, leaving permanent scarring alopecia and atrophy.")],
  histo=["Interface dermatitis, follicular plugging, thickened basement membrane, perivascular and periadnexal lymphocytes, dermal mucin; DIF: lupus band."],
  special=[{"t": "**Skin of colour**", "sub": ["Marked hyper- and depigmentation; high scarring risk."]}],
  comp=["Scarring alopecia, disfigurement, SCC in scars, progression to SLE."],
  prog=["Chronic; early treatment limits scarring."],
  see_also=["scarring-alopecia", "dermatomyositis", "polymorphic-light-eruption", "sarcoidosis", "psoriasis"])

E('pemphigus',
  kf=["**Pemphigus vulgaris** is a rare autoimmune blistering disease with **flaccid blisters and erosions**, almost always involving the **mouth**.",
      "Autoantibodies to **desmogleins 3 (± 1)** separate keratinocytes (acantholysis): **Nikolsky sign** positive.",
      "Oral erosions often precede skin lesions by months; pemphigus foliaceus (Dsg1) spares the mucosa.",
      "Extensive or unwell: **same-day admission**; mucosal only: urgent dermatology.",
      "Specialist first line: **rituximab plus prednisolone**; untreated mortality is high."],
  epi=[{"t": "**Who**", "sub": ["Adults 40–60; more common in Ashkenazi Jewish and Mediterranean, South Asian populations."]}],
  myths=["**\"Recurrent mouth ulcers are just aphthous\"**: persistent oral erosions in an adult need biopsy."],
  patho_lead="Antibodies **cut the glue (desmosomes)** between epidermal cells, so the epidermis falls apart.",
  mech=[("Autoantibodies", "IgG binds desmoglein 3 (mucosal) and desmoglein 1 (skin)."),
        ("Acantholysis", "Keratinocytes lose adhesion and separate just above the basal layer."),
        ("Flaccid blister", "The thin roof ruptures easily, leaving painful erosions.", "v3-bp-vs-pv-split.jpg", "Pemphigus splits within the epidermis (flaccid blister); pemphigoid splits beneath it (tense blister)."),
        ("Desmoglein compensation", "Which desmogleins are targeted explains mucosal versus skin involvement.")],
  histo=["Suprabasal acantholysis with 'tombstone' basal cells; DIF: intercellular IgG and C3 ('fishnet'); serum Dsg1/Dsg3 ELISA."],
  special=[{"t": "**Drug-induced and paraneoplastic pemphigus**", "sub": ["Penicillamine, ACE inhibitors; paraneoplastic pemphigus with lymphoma causes severe stomatitis."]}],
  comp=["Dehydration, malnutrition, sepsis, steroid side effects; death without treatment."],
  prog=["Controlled in most with modern treatment; relapses occur."],
  see_also=["bullous-pemphigoid", "blistering-approach", "dermatitis-herpetiformis", "drug-induced-blistering"])

E('dermatitis-herpetiformis',
  kf=["**Dermatitis herpetiformis (DH)** is the skin manifestation of **coeliac disease**: intensely itchy grouped vesicles.",
      "Extensor elbows, knees, buttocks and scalp; usually seen as excoriations rather than intact blisters.",
      "Confirm with **biopsy and direct IF** (granular IgA in dermal papillae) and coeliac serology **before** a gluten-free diet.",
      "**Lifelong gluten-free diet** treats skin and gut; **dapsone** controls itch within days (specialist; check G6PD).",
      "Refer to gastroenterology (NICE NG20); screen for associated autoimmunity."],
  epi=[{"t": "**Who**", "sub": ["Adults 30–40; men slightly more; about 1 in 10,000 in the UK; most have enteropathy, often silent."]}],
  myths=["**\"No gut symptoms, so not coeliac\"**: most people with DH have silent enteropathy."],
  patho_lead="Gut-made **IgA antibodies to transglutaminase** deposit in the skin.",
  mech=[("Gluten in the gut", "Gluten triggers an immune response in genetically susceptible people (HLA-DQ2/DQ8)."),
        ("IgA to epidermal TG3", "IgA antibodies against tissue and epidermal transglutaminase (TG3) circulate."),
        ("Papillary deposits", "IgA–TG3 complexes deposit at the tips of dermal papillae and attract neutrophils.", "v4-dh-papillary-iga.jpg", "Dermatitis herpetiformis: granular IgA deposits (yellow) and neutrophils at the dermal papillary tips create tiny blisters beneath the epidermis."),
        ("Clearance", "On a gluten-free diet, deposits fade over months to years.")],
  histo=["Neutrophilic microabscesses in dermal papillae with subepidermal clefts; DIF of perilesional skin: granular IgA in papillae."],
  special=[{"t": "**Dapsone safety**", "sub": ["Check G6PD; monitor FBC and LFT for haemolysis, methaemoglobinaemia and agranulocytosis."]}],
  comp=["Small-bowel lymphoma risk (reduced by gluten-free diet); osteoporosis, anaemia; associated thyroid disease and type 1 diabetes."],
  prog=["Lifelong; remission on strict gluten-free diet."],
  see_also=["bullous-pemphigoid", "pemphigus", "scabies", "blistering-approach", "eczema-dermatitis"])

E('sarcoidosis',
  kf=["**Sarcoidosis** is a multisystem **non-caseating granulomatous** disease; the skin is involved in about a quarter.",
      "Specific lesions: red-brown papules and plaques (face, scars, tattoos), **lupus pernio** (nose, cheeks); non-specific: **erythema nodosum**.",
      "Apple-jelly colour on diascopy; infiltration of old scars and tattoos is a clue.",
      "Investigate: biopsy, chest X-ray, calcium, ACE, U&E, LFT, ECG, eye review.",
      "Mild skin disease: potent or intralesional steroid; extensive or systemic: specialist (hydroxychloroquine, methotrexate, TNF inhibitors)."],
  epi=[{"t": "**Who**", "sub": ["Adults 25–45; more common and severe in people of African descent; Scandinavian peak."]}],
  myths=["**\"Skin sarcoid is just cosmetic\"**: lupus pernio is linked with chronic lung and upper airway disease."],
  patho_lead="Sarcoidosis is an **over-exuberant granuloma response** to an unknown antigen.",
  mech=[("Antigen", "An unknown antigen (possibly mycobacterial or environmental) is presented to CD4+ T cells."),
        ("Th1/Th17 response", "Interferon-γ and TNF-α activate macrophages."),
        ("Granuloma formation", "Epithelioid macrophages and giant cells form tight 'naked' granulomas in the dermis."),
        ("Organ involvement", "The same process in lungs, eyes, heart and lymph nodes causes systemic disease.")],
  histo=["Non-caseating 'naked' epithelioid granulomas with few lymphocytes; stains for mycobacteria and fungi negative."],
  special=[{"t": "**Löfgren syndrome**", "sub": ["Erythema nodosum, bilateral hilar lymphadenopathy, fever and ankle arthritis: good prognosis."]}],
  comp=["Lung fibrosis, uveitis, cardiac arrhythmia, hypercalcaemia, renal stones; disfigurement from lupus pernio."],
  prog=["Löfgren usually resolves; lupus pernio and plaques tend to be chronic."],
  see_also=["erythema-nodosum", "discoid-lupus", "cutaneous-tuberculosis", "annular-rashes", "lung-cancer-skin-signs"])

E('trichotillomania',
  kf=["**Trichotillomania** is recurrent hair pulling causing hair loss: a **body-focused repetitive behaviour** (OCD-related disorder).",
      "Irregular patches with hairs of **different lengths**, broken hairs, often on the side of the dominant hand; scalp, brows, lashes.",
      "Many deny pulling; dermoscopy shows broken hairs, coiled hairs and 'flame' hairs.",
      "First-line: **habit reversal therapy** (CBT); treat associated anxiety or depression.",
      "Ask about **trichophagia** (eating hair): risk of trichobezoar."],
  epi=[{"t": "**Who**", "sub": ["1–2% lifetime; children (often self-limiting) and young women; associated with anxiety, OCD and depression."]}],
  myths=["**\"It's just a bad habit\"**: it is a recognised mental health condition that responds to specific therapy."],
  patho_lead="Repeated pulling **mechanically breaks** hairs, which regrow normally if pulling stops.",
  mech=[("Urge and relief", "Tension or boredom builds; pulling gives relief or pleasure, reinforcing the behaviour."),
        ("Mechanical damage", "Hairs fracture at different lengths; follicles bleed or become distorted."),
        ("Regrowth", "Follicles are not destroyed early on, so hair regrows if pulling stops; chronic pulling can scar.")],
  histo=["Rarely needed: trichomalacia, pigment casts, empty follicles and increased catagen hairs without inflammation."],
  special=[{"t": "**Children**", "sub": ["Early-onset pulling often settles; support parents without punishment."]}],
  comp=["Permanent alopecia, infection, shame and social isolation; trichobezoar."],
  prog=["Chronic and fluctuating in adults; good outcomes with habit reversal therapy."],
  see_also=["alopecia-areata", "tinea", "scarring-alopecia", "telogen-effluvium"])

E('hyperhidrosis',
  kf=["**Hyperhidrosis** is sweating beyond what is needed for temperature control; **primary focal** (axillae, palms, soles, face) or **secondary generalised**.",
      "Primary: starts in childhood or adolescence, bilateral and symmetrical, absent during sleep, family history.",
      "Secondary: generalised or night sweats, later onset: look for drugs (SSRIs), endocrine disease, infection, malignancy.",
      "Aluminium chloride hexahydrate 20% at night; then iontophoresis (palms/soles), botulinum toxin, oral anticholinergics (specialist).",
      "Huge quality-of-life impact; ask about anxiety and social avoidance."],
  epi=[{"t": "**Who**", "sub": ["About 1–3% of people; onset in childhood or adolescence for primary focal hyperhidrosis."]}],
  myths=["**\"It's just nerves\"**: anxiety worsens it, but primary hyperhidrosis is a physiological overactivity of sweat glands."],
  patho_lead="Sweat glands are normal; the **nerves driving them are overactive**.",
  mech=[("Central drive", "Hypothalamic and emotional centres send excess sympathetic signals."),
        ("Cholinergic nerves", "Sympathetic fibres release acetylcholine onto eccrine glands.", "v4-hyperhidrosis-eccrine.jpg", "Overactive sympathetic nerve fibres (cholinergic) wrap around eccrine sweat glands, driving excess sweat to the surface."),
        ("Eccrine output", "Glands secrete large volumes onto palms, soles and axillae."),
        ("Treatment targets", "Aluminium salts plug ducts; botulinum toxin blocks acetylcholine; anticholinergics block receptors.")],
  histo=["Not needed; sweat glands are histologically normal."],
  special=[{"t": "**Secondary causes to exclude**", "sub": ["Hyperthyroidism, diabetes, menopause, phaeochromocytoma, TB, lymphoma, drugs (SSRIs, opioids)."]}],
  comp=["Maceration, pitted keratolysis, fungal infection, eczema; social and occupational disability."],
  prog=["Primary hyperhidrosis often persists for years but can improve with age."],
  see_also=["keratolysis-exfoliativa", "hand-eczema", "tinea", "botulinum" if False else "facial-ageing-neuromodulators"])

E('hirsutism',
  kf=["**Hirsutism** is excess terminal hair in women in a **male pattern** (upper lip, chin, chest, abdomen, back).",
      "Commonest cause: **PCOS**; also idiopathic hirsutism, congenital adrenal hyperplasia, drugs; rarely androgen-secreting tumours.",
      "Red flags: **rapid onset**, virilisation (deep voice, clitoromegaly), very high testosterone: urgent endocrine referral.",
      "Check testosterone (± SHBG, LH/FSH, prolactin, 17-OH progesterone); weight loss; hair removal; COC; eflornithine for the face.",
      "Effects of hormonal treatment take 6–12 months."],
  epi=[{"t": "**Who**", "sub": ["5–10% of women of reproductive age; varies by ethnicity."]}],
  myths=["**\"Shaving makes hair thicker\"**: it does not."],
  patho_lead="Androgens convert fine **vellus hairs into thick terminal hairs** in sensitive follicles.",
  mech=[("Androgen excess or sensitivity", "Higher androgens (PCOS) or more sensitive follicles (idiopathic)."),
        ("5α-reductase", "Follicles convert testosterone to DHT."),
        ("Vellus to terminal", "DHT enlarges follicles, producing coarse pigmented hairs.", "v3-vellus-to-terminal.jpg", "Androgens transform fine vellus hairs into coarse terminal hairs."),
        ("Treatment", "COCs raise SHBG and lower androgens; laser targets hair melanin.", "v3-laser-hair-removal.jpg", "Laser hair removal targets the pigmented hair follicle.")],
  special=[{"t": "**Hypertrichosis**", "sub": ["Generalised non-androgenic hair growth (drugs such as minoxidil, ciclosporin; anorexia): different investigations."]}],
  comp=["Psychological distress; folliculitis and PIH from hair removal."],
  prog=["Chronic; controlled with combined treatment."],
  see_also=["acne-vulgaris", "androgenetic-alopecia", "acanthosis-nigricans", "acne-prescribing-combined-pill", "intense-pulsed-light"])

E('acanthosis-nigricans',
  kf=["**Acanthosis nigricans** is velvety brown-black thickening of the skin in the **neck, axillae and groin**.",
      "Commonest cause: **insulin resistance** (obesity, type 2 diabetes, PCOS); also drugs, endocrine disease, inherited forms.",
      "Sudden extensive AN with mucosal or palm involvement ('tripe palms') or weight loss: **malignant AN** (gastric adenocarcinoma).",
      "Check HbA1c or glucose and lipids; treat the cause (weight loss improves it).",
      "Topical retinoids or keratolytics for appearance."],
  epi=[{"t": "**Who**", "sub": ["Common in obese adolescents and adults; more visible in darker skin."]}],
  myths=["**\"It's dirt\"**: it does not wash off and signals insulin resistance."],
  patho_lead="High insulin acts like a **growth factor** on keratinocytes and fibroblasts.",
  mech=[("Hyperinsulinaemia", "Insulin resistance raises circulating insulin."),
        ("IGF-1 receptor stimulation", "At high levels insulin activates IGF-1 receptors on keratinocytes."),
        ("Papillomatosis", "The epidermis thickens into velvety folds; pigment is mostly from the thick keratin."),
        ("Malignant AN", "Tumour growth factors (TGF-α) cause sudden, extensive disease.")],
  histo=["Papillomatosis and hyperkeratosis with mild acanthosis; little increase in melanin."],
  special=[{"t": "**Malignant acanthosis nigricans**", "sub": ["Rapid onset in older non-obese adults, mucosal involvement, tripe palms: urgent investigation for cancer."]}],
  comp=["Marker of diabetes and cardiovascular risk."],
  prog=["Improves with weight loss and insulin sensitisation; malignant AN tracks the cancer."],
  see_also=["hirsutism", "lung-cancer-skin-signs", "intertrigo", "cushings-syndrome-skin"])

E('red-leg',
  kf=["The **red leg** is a common diagnostic trap: most bilateral red legs are **not cellulitis**.",
      "Cellulitis is usually **unilateral**, acute, hot, tender, spreading, with fever or raised inflammatory markers.",
      "Mimics: venous (stasis) eczema, lipodermatosclerosis, contact dermatitis, DVT, haematoma, gout, erythema nodosum, vasculitis.",
      "Bilateral red legs: treat the cause (compression, emollient, steroid for eczema); avoid unnecessary antibiotics.",
      "Same-day: sepsis, rapidly spreading, severe pain out of proportion (necrotising fasciitis), suspected DVT."],
  epi=[{"t": "**Who**", "sub": ["Up to a third of patients admitted with 'cellulitis' have a mimic, often stasis dermatitis."]}],
  myths=["**\"Both legs red means double cellulitis\"**: bilateral cellulitis is rare."],
  patho_lead="Different processes make legs red: **infection, venous hypertension, allergy, thrombosis or inflammation**.",
  mech=[("Venous hypertension", "Stasis causes oedema, inflammation and eczema (bilateral, itchy, chronic)."),
        ("Infection", "Bacteria enter via breaks (tinea, ulcers) and spread through dermis and fat (unilateral, acute)."),
        ("Contact allergy", "Dressings and topical medicines cause itchy, sharply bordered eczema."),
        ("Thrombosis", "DVT causes swollen, tender calf with warmth: Wells score and D-dimer.")],
  special=[{"t": "**Necrotising fasciitis**", "sub": ["Pain out of proportion, rapid spread, systemic toxicity, crepitus: emergency surgery."]}],
  comp=["Unnecessary antibiotics and admissions; missed DVT or necrotising infection."],
  prog=["Depends on cause; stasis dermatitis is chronic and needs compression."],
  see_also=["cellulitis-erysipelas", "venous-leg-ulcer", "contact-dermatitis", "erythema-nodosum", "eczema-dermatitis"])

E('neonatal-rashes',
  kf=["Most neonatal rashes are **benign and transient**: erythema toxicum neonatorum (ETN), transient neonatal pustular melanosis (TNPM), miliaria, milia and neonatal acne.",
      "ETN: blotchy red macules with central pustules in days 1–3; spares palms and soles; eosinophils.",
      "TNPM: pustules at birth that rupture to leave collarettes and brown macules, more in darker skin.",
      "Miliaria: blocked sweat ducts from overheating; clear vesicles (crystallina) or red papules (rubra).",
      "Red flags: unwell baby, vesicles (**HSV**: emergency aciclovir), purpura, blistering, widespread pustules with fever."],
  epi=[{"t": "**Who**", "sub": ["ETN affects up to half of term babies; TNPM about 5% of Black infants; miliaria in hot, overwrapped babies."]}],
  myths=["**\"Spots in a newborn mean infection\"**: most are harmless, but vesicles or an unwell baby need urgent review."],
  patho_lead="Newborn skin is **adapting** to air, bacteria and temperature regulation.",
  mech=[("Immune adaptation", "ETN reflects an innate immune response to colonising bacteria at hair follicles (eosinophils)."),
        ("Sweat duct immaturity", "Immature ducts block easily, causing miliaria when overheated.", "v4-milia-section.jpg", "Milia: tiny keratin cysts common on newborn noses and cheeks."),
        ("Maternal hormones", "Maternal androgens stimulate sebaceous glands (neonatal acne, sebaceous hyperplasia).")],
  special=[{"t": "**Neonatal HSV**", "sub": ["Grouped vesicles, especially on the scalp or presenting part, with or without fever: emergency IV aciclovir."]}],
  comp=["Rarely, misdiagnosis of infection; miliaria pustulosa can become infected."],
  prog=["ETN and TNPM resolve within days to weeks (TNPM pigment within months)."],
  see_also=["neonatal-infantile-acne", "milia", "napkin-dermatitis", "infantile-haemangioma", "herpes-simplex-labialis"])

E('neonatal-infantile-acne',
  kf=["**Neonatal acne** (cephalic pustulosis) appears in the first weeks: papules and pustules on the cheeks; **no comedones**; settles in weeks.",
      "**Infantile acne** starts at 3–6 months with **comedones**, papules and sometimes nodules; may last 1–2 years and scar.",
      "Infantile acne needs examination for signs of virilisation or early puberty (refer if present).",
      "Neonatal: reassure, gentle washing; infantile: topical benzoyl peroxide or retinoid; erythromycin if moderate (tetracyclines contraindicated).",
      "Severe or scarring infantile acne: refer (may need isotretinoin)."],
  epi=[{"t": "**Who**", "sub": ["Neonatal acne affects up to 20% of newborns; infantile acne is less common, more in boys."]}],
  myths=["**\"Baby acne means the baby will have bad teenage acne\"**: neonatal acne does not; infantile acne may predict later acne."],
  patho_lead="**Maternal and infant androgens** briefly stimulate the baby's sebaceous glands.",
  mech=[("Hormonal stimulus", "Maternal androgens (neonatal) and transient infant adrenal and testicular androgens (infantile) enlarge sebaceous glands."),
        ("Malassezia (neonatal)", "Neonatal cephalic pustulosis may be a reaction to Malassezia yeasts.", "v3-neonatal-acne-face.jpg", "Neonatal acne: papules and pustules on the cheeks, no comedones."),
        ("Comedones (infantile)", "Follicular plugging creates true comedones and inflammatory lesions.", "v3-acne-follicle-stages.jpg", "Acne follicle stages from microcomedone to inflamed papule.")],
  special=[{"t": "**Red flags in infantile acne**", "sub": ["Growth acceleration, body odour, pubic hair, clitoromegaly or testicular enlargement: paediatric endocrinology."]}],
  comp=["Scarring (infantile nodular acne); parental anxiety."],
  prog=["Neonatal: resolves by 3 months. Infantile: usually by 2 years."],
  see_also=["neonatal-rashes", "acne-vulgaris", "milia", "napkin-dermatitis"])
